INSERT INTO DeanPriorities (FiscalYear, Code, Title, Description, PriorityID, PercentComplete) VALUES
  (26, 'D26-1', 'Strategy ''35 Develop', 'Complete the development of Strategy ''35, establishing a clear strategic direction and framework for CLL''s long-term priorities.', (SELECT PriorityID FROM Priorities WHERE Code='P06'), 100),
  (26, 'D26-2', 'GT Infinity 1.0 Prototype', 'Complete the GT Infinity 1.0 prototype to demonstrate the core learner experience and validate the foundation for future development.', (SELECT PriorityID FROM Priorities WHERE Code='P02'), 100),
  (26, 'D26-3', 'Restruct / Budget Model', 'Complete the organizational restructuring and budget model to align roles, resources, and financial decisions with CLL''s strategic priorities.', (SELECT PriorityID FROM Priorities WHERE Code='P05'), 100),
  (27, 'D27-1', 'Department of Learning Systems', 'Establish the Department of Learning Systems to support innovative program development, academic approvals, faculty assignment, and program recruitment.', (SELECT PriorityID FROM Priorities WHERE Code='P03'), 20),
  (27, 'D27-2', 'Digital Credentials', 'Expand the use of digital credentials by identifying programs for adoption, integrating credentials with GT Infinity 2.0, and connecting to external credentialing networks.', (SELECT PriorityID FROM Priorities WHERE Code='P03'), 5),
  (27, 'D27-3', 'GT Infinity 2.0 Public', 'Launch GT Infinity 2.0 publicly with a high-quality user experience that supports multimodal learning units, personalization, and integrated digital credentials.', (SELECT PriorityID FROM Priorities WHERE Code='P04'), 10),
  (27, 'D27-4', 'OMS AI', 'Advance OMS AI through required approvals and recruitment, develop a Learning Innovation concentration, and establish the research team and plan.', (SELECT PriorityID FROM Priorities WHERE Code='P02'), 50),
  (27, 'D27-5', 'Environmental Scan — Lifelong Learning', 'Conduct an environmental scan of lifelong learning to identify market trends, learner needs, competitive activity, and opportunities that can inform CLL strategy and investment.', (SELECT PriorityID FROM Priorities WHERE Code='P01'), 80),
  (27, 'D27-6', 'Financial & Labor Optimization', 'Integrate financial insights into the operating model, clarify labor requirements, improve efficiency, and create systems that provide transparent, actionable information.', (SELECT PriorityID FROM Priorities WHERE Code='P05'), 0),
  (27, 'D27-7', 'Restructure — 4 Learning Teams', 'Design and implement the four learning-team operating model across Learning Infrastructure, Learning Ecosystems, Learning Experiences, and Learning Futures.', (SELECT PriorityID FROM Priorities WHERE Code='P01'), 10),
  (27, 'D27-8', 'Consult GT', 'Create a consulting mechanism that enables CLL to share its expertise with higher education institutions seeking support with transformation and improvement.', (SELECT PriorityID FROM Priorities WHERE Code='P06'), 5);
